// Async support
// Async return type handlers

internal const val UNIFFI_RUST_FUTURE_POLL_READY = 0.toByte()
internal const val UNIFFI_RUST_FUTURE_POLL_WAKE = 1.toByte()

internal val uniffiContinuationHandleMap = UniffiHandleMap<CancellableContinuation<Byte>>()

// FFI type for Rust future continuations
internal object uniffiRustFutureContinuationCallbackImpl: UniffiRustFutureContinuationCallback {
    override fun callback(data: Long, pollResult: Byte) {
        uniffiContinuationHandleMap.remove(data).resume(pollResult)
    }
}

internal suspend fun<T, F, E: kotlin.Exception> uniffiRustCallAsync(
    rustFuture: Long,
    pollFunc: (Long, UniffiRustFutureContinuationCallback, Long) -> Unit,
    completeFunc: (Long, UniffiRustCallStatus) -> F,
    freeFunc: (Long) -> Unit,
    liftFunc: (F) -> T,
    errorHandler: UniffiRustCallStatusErrorHandler<E>
): T {
    try {
        do {
            val pollResult = suspendCancellableCoroutine<Byte> { continuation ->
                pollFunc(
                    rustFuture,
                    uniffiRustFutureContinuationCallbackImpl,
                    uniffiContinuationHandleMap.insert(continuation)
                )
            }
        } while (pollResult != UNIFFI_RUST_FUTURE_POLL_READY);

        return liftFunc(
            uniffiRustCallWithError(errorHandler, { status -> completeFunc(rustFuture, status) })
        )
    } finally {
        freeFunc(rustFuture)
    }
}

// Public interface members begin here.


// Interface implemented by anything that can contain an object reference.
//
// Such types expose a `destroy()` method that must be called to cleanly
// dispose of the contained objects. Failure to call this method may result
// in memory leaks.
//
// The easiest way to ensure this method is called is to use the `.use`
// helper method to execute a block and destroy the object at the end.
interface Disposable {
    fun destroy()
    companion object {
        fun destroy(vararg args: Any?) {
            for (arg in args) {
                when (arg) {
                    is Disposable -> arg.destroy()
                    is ArrayList<*> -> {
                        for (idx in arg.indices) {
                            val element = arg[idx]
                            if (element is Disposable) {
                                element.destroy()
                            }
                        }
                    }
                    is Map<*, *> -> {
                        for (element in arg.values) {
                            if (element is Disposable) {
                                element.destroy()
                            }
                        }
                    }
                    is Iterable<*> -> {
                        for (element in arg) {
                            if (element is Disposable) {
                                element.destroy()
                            }
                        }
                    }
                }
            }
        }
    }
}

/**
 * @suppress
 */
inline fun <T : Disposable?, R> T.use(block: (T) -> R) =
    try {
        block(this)
    } finally {
        try {
            // N.B. our implementation is on the nullable type `Disposable?`.
            this?.destroy()
        } catch (e: Throwable) {
            // swallow
        }
    }

/** 
 * Placeholder object used to signal that we're constructing an interface with a FFI handle.
 *
 * This is the first argument for interface constructors that input a raw handle. It exists is that
 * so we can avoid signature conflicts when an interface has a regular constructor than inputs a
 * Long.
 *
 * @suppress
 * */
object UniffiWithHandle

/** 
 * Used to instantiate an interface without an actual pointer, for fakes in tests, mostly.
 *
 * @suppress
 * */
object NoHandle// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
internal const val IDX_CALLBACK_FREE = 0
// Callback return codes
internal const val UNIFFI_CALLBACK_SUCCESS = 0
internal const val UNIFFI_CALLBACK_ERROR = 1
internal const val UNIFFI_CALLBACK_UNEXPECTED_ERROR = 2

/**
 * @suppress
 */
public abstract class FfiConverterCallbackInterface<CallbackInterface: Any>: FfiConverter<CallbackInterface, Long> {
    internal val handleMap = UniffiHandleMap<CallbackInterface>()

    internal fun drop(handle: Long) {
        handleMap.remove(handle)
    }

    override fun lift(value: Long): CallbackInterface {
        return handleMap.get(value)
    }

    override fun read(buf: ByteBuffer) = lift(buf.getLong())

    override fun lower(value: CallbackInterface) = handleMap.insert(value)

    override fun allocationSize(value: CallbackInterface) = 8UL

    override fun write(value: CallbackInterface, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}
/**
 * The cleaner interface for Object finalization code to run.
 * This is the entry point to any implementation that we're using.
 *
 * The cleaner registers objects and returns cleanables, so now we are
 * defining a `UniffiCleaner` with a `UniffiClenaer.Cleanable` to abstract the
 * different implmentations available at compile time.
 *
 * @suppress
 */
interface UniffiCleaner {
    interface Cleanable {
        fun clean()
    }

    fun register(value: Any, cleanUpTask: Runnable): UniffiCleaner.Cleanable

    companion object
}

// The fallback Jna cleaner, which is available for both Android, and the JVM.
private class UniffiJnaCleaner : UniffiCleaner {
    private val cleaner = com.sun.jna.internal.Cleaner.getCleaner()

    override fun register(value: Any, cleanUpTask: Runnable): UniffiCleaner.Cleanable =
        UniffiJnaCleanable(cleaner.register(value, cleanUpTask))
}

private class UniffiJnaCleanable(
    private val cleanable: com.sun.jna.internal.Cleaner.Cleanable,
) : UniffiCleaner.Cleanable {
    override fun clean() = cleanable.clean()
}


// We decide at uniffi binding generation time whether we were
// using Android or not.
// There are further runtime checks to chose the correct implementation
// of the cleaner.
private fun UniffiCleaner.Companion.create(): UniffiCleaner =
    try {
        // For safety's sake: if the library hasn't been run in android_cleaner = true
        // mode, but is being run on Android, then we still need to think about
        // Android API versions.
        // So we check if java.lang.ref.Cleaner is there, and use that…
        java.lang.Class.forName("java.lang.ref.Cleaner")
        JavaLangRefCleaner()
    } catch (e: ClassNotFoundException) {
        // … otherwise, fallback to the JNA cleaner.
        UniffiJnaCleaner()
    }

private class JavaLangRefCleaner : UniffiCleaner {
    val cleaner = java.lang.ref.Cleaner.create()

    override fun register(value: Any, cleanUpTask: Runnable): UniffiCleaner.Cleanable =
        JavaLangRefCleanable(cleaner.register(value, cleanUpTask))
}

private class JavaLangRefCleanable(
    val cleanable: java.lang.ref.Cleaner.Cleanable
) : UniffiCleaner.Cleanable {
    override fun clean() = cleanable.clean()
}

/**
 * @suppress
 */
public object FfiConverterUInt: FfiConverter<UInt, Int> {
    override fun lift(value: Int): UInt {
        return value.toUInt()
    }

    override fun read(buf: ByteBuffer): UInt {
        return lift(buf.getInt())
    }

    override fun lower(value: UInt): Int {
        return value.toInt()
    }

    override fun allocationSize(value: UInt) = 4UL

    override fun write(value: UInt, buf: ByteBuffer) {
        buf.putInt(value.toInt())
    }
}

/**
 * @suppress
 */
public object FfiConverterULong: FfiConverter<ULong, Long> {
    override fun lift(value: Long): ULong {
        return value.toULong()
    }

    override fun read(buf: ByteBuffer): ULong {
        return lift(buf.getLong())
    }

    override fun lower(value: ULong): Long {
        return value.toLong()
    }

    override fun allocationSize(value: ULong) = 8UL

    override fun write(value: ULong, buf: ByteBuffer) {
        buf.putLong(value.toLong())
    }
}

/**
 * @suppress
 */
public object FfiConverterLong: FfiConverter<Long, Long> {
    override fun lift(value: Long): Long {
        return value
    }

    override fun read(buf: ByteBuffer): Long {
        return buf.getLong()
    }

    override fun lower(value: Long): Long {
        return value
    }

    override fun allocationSize(value: Long) = 8UL

    override fun write(value: Long, buf: ByteBuffer) {
        buf.putLong(value)
    }
}

/**
 * @suppress
 */
public object FfiConverterBoolean: FfiConverter<Boolean, Byte> {
    override fun lift(value: Byte): Boolean {
        return value.toInt() != 0
    }

    override fun read(buf: ByteBuffer): Boolean {
        return lift(buf.get())
    }

    override fun lower(value: Boolean): Byte {
        return if (value) 1.toByte() else 0.toByte()
    }

    override fun allocationSize(value: Boolean) = 1UL

    override fun write(value: Boolean, buf: ByteBuffer) {
        buf.put(lower(value))
    }
}

/**
 * @suppress
 */
public object FfiConverterString: FfiConverter<String, RustBuffer.ByValue> {
    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    override fun lift(value: RustBuffer.ByValue): String {
        try {
            val byteArr = ByteArray(value.len.toInt())
            value.asByteBuffer()!!.get(byteArr)
            return byteArr.toString(Charsets.UTF_8)
        } finally {
            RustBuffer.free(value)
        }
    }

    override fun read(buf: ByteBuffer): String {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr.toString(Charsets.UTF_8)
    }

    fun toUtf8(value: String): ByteBuffer {
        // Make sure we don't have invalid UTF-16, check for lone surrogates.
        return Charsets.UTF_8.newEncoder().run {
            onMalformedInput(CodingErrorAction.REPORT)
            encode(CharBuffer.wrap(value))
        }
    }

    override fun lower(value: String): RustBuffer.ByValue {
        val byteBuf = toUtf8(value)
        // Ideally we'd pass these bytes to `ffi_bytebuffer_from_bytes`, but doing so would require us
        // to copy them into a JNA `Memory`. So we might as well directly copy them into a `RustBuffer`.
        val rbuf = RustBuffer.alloc(byteBuf.limit().toULong())
        rbuf.asByteBuffer()!!.put(byteBuf)
        return rbuf
    }

    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per UTF-16 code unit which will always be
    // enough.
    override fun allocationSize(value: String): ULong {
        val sizeForLength = 4UL
        val sizeForString = value.length.toULong() * 3UL
        return sizeForLength + sizeForString
    }

    override fun write(value: String, buf: ByteBuffer) {
        val byteBuf = toUtf8(value)
        buf.putInt(byteBuf.limit())
        buf.put(byteBuf)
    }
}

/**
 * @suppress
 */
public object FfiConverterByteArray: FfiConverterRustBuffer<ByteArray> {
    override fun read(buf: ByteBuffer): ByteArray {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr
    }
    override fun allocationSize(value: ByteArray): ULong {
        return 4UL + value.size.toULong()
    }
    override fun write(value: ByteArray, buf: ByteBuffer) {
        buf.putInt(value.size)
        buf.put(value)
    }
}


// This template implements a class for working with a Rust struct via a handle
// to the live Rust struct on the other side of the FFI.
//
// There's some subtlety here, because we have to be careful not to operate on a Rust
// struct after it has been dropped, and because we must expose a public API for freeing
// theq Kotlin wrapper object in lieu of reliable finalizers. The core requirements are:
//
//   * Each instance holds an opaque handle to the underlying Rust struct.
//     Method calls need to read this handle from the object's state and pass it in to
//     the Rust FFI.
//
//   * When an instance is no longer needed, its handle should be passed to a
//     special destructor function provided by the Rust FFI, which will drop the
//     underlying Rust struct.
//
//   * Given an instance, calling code is expected to call the special
//     `destroy` method in order to free it after use, either by calling it explicitly
//     or by using a higher-level helper like the `use` method. Failing to do so risks
//     leaking the underlying Rust struct.
//
//   * We can't assume that calling code will do the right thing, and must be prepared
//     to handle Kotlin method calls executing concurrently with or even after a call to
//     `destroy`, and to handle multiple (possibly concurrent!) calls to `destroy`.
//
//   * We must never allow Rust code to operate on the underlying Rust struct after
//     the destructor has been called, and must never call the destructor more than once.
//     Doing so may trigger memory unsafety.
//
//   * To mitigate many of the risks of leaking memory and use-after-free unsafety, a `Cleaner`
//     is implemented to call the destructor when the Kotlin object becomes unreachable.
//     This is done in a background thread. This is not a panacea, and client code should be aware that
//      1. the thread may starve if some there are objects that have poorly performing
//     `drop` methods or do significant work in their `drop` methods.
//      2. the thread is shared across the whole library. This can be tuned by using `android_cleaner = true`,
//         or `android = true` in the [`kotlin` section of the `uniffi.toml` file](https://mozilla.github.io/uniffi-rs/kotlin/configuration.html).
//
// If we try to implement this with mutual exclusion on access to the handle, there is the
// possibility of a race between a method call and a concurrent call to `destroy`:
//
//    * Thread A starts a method call, reads the value of the handle, but is interrupted
//      before it can pass the handle over the FFI to Rust.
//    * Thread B calls `destroy` and frees the underlying Rust struct.
//    * Thread A resumes, passing the already-read handle value to Rust and triggering
//      a use-after-free.
//
// One possible solution would be to use a `ReadWriteLock`, with each method call taking
// a read lock (and thus allowed to run concurrently) and the special `destroy` method
// taking a write lock (and thus blocking on live method calls). However, we aim not to
// generate methods with any hidden blocking semantics, and a `destroy` method that might
// block if called incorrectly seems to meet that bar.
//
// So, we achieve our goals by giving each instance an associated `AtomicLong` counter to track
// the number of in-flight method calls, and an `AtomicBoolean` flag to indicate whether `destroy`
// has been called. These are updated according to the following rules:
//
//    * The initial value of the counter is 1, indicating a live object with no in-flight calls.
//      The initial value for the flag is false.
//
//    * At the start of each method call, we atomically check the counter.
//      If it is 0 then the underlying Rust struct has already been destroyed and the call is aborted.
//      If it is nonzero them we atomically increment it by 1 and proceed with the method call.
//
//    * At the end of each method call, we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
//    * When `destroy` is called, we atomically flip the flag from false to true.
//      If the flag was already true we silently fail.
//      Otherwise we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
// Astute readers may observe that this all sounds very similar to the way that Rust's `Arc<T>` works,
// and indeed it is, with the addition of a flag to guard against multiple calls to `destroy`.
//
// The overall effect is that the underlying Rust struct is destroyed only when `destroy` has been
// called *and* all in-flight method calls have completed, avoiding violating any of the expectations
// of the underlying Rust code.
//
// This makes a cleaner a better alternative to _not_ calling `destroy()` as
// and when the object is finished with, but the abstraction is not perfect: if the Rust object's `drop`
// method is slow, and/or there are many objects to cleanup, and it's on a low end Android device, then the cleaner
// thread may be starved, and the app will leak memory.
//
// In this case, `destroy`ing manually may be a better solution.
//
// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


/**
 * The core, as one object the foreign side holds.
 */
public interface CoreAppInterface {
    
    /**
     * Accept the verification with the given flow ID; the emojis arrive
     * through the listener when both sides are ready.
     */
    suspend fun `acceptVerification`(`flowId`: kotlin.String)
    
    /**
     * Cancel the verification — the emojis did not match, or the user
     * declined.
     */
    suspend fun `cancelVerification`(`flowId`: kotlin.String)
    
    /**
     * Move the given room to the given category: accepting an invite is a
     * move to Normal, declining it (or leaving) a move to Left.
     */
    suspend fun `changeRoomCategory`(`roomId`: kotlin.String, `category`: FfiTargetRoomCategory)
    
    /**
     * Stop feeding the member-list listener.
     */
    fun `clearMemberListListener`()
    
    /**
     * Stop feeding the pinned-events listener.
     */
    fun `clearPinnedListener`()
    
    /**
     * Stop pushing thread updates.
     */
    fun `clearThreadListener`()
    
    /**
     * Confirm that the emojis matched.
     */
    suspend fun `confirmVerification`(`flowId`: kotlin.String)
    
    /**
     * Open a direct chat with the given user: the existing one when
     * there is one, a newly created encrypted DM otherwise. Returns the
     * room ID.
     */
    suspend fun `createDirectChat`(`userId`: kotlin.String): kotlin.String
    
    /**
     * Replace the given event's content with the given plain text.
     */
    suspend fun `editMessage`(`roomId`: kotlin.String, `eventId`: kotlin.String, `newBody`: kotlin.String)
    
    /**
     * Set up recovery, returning the recovery key to write down.
     */
    suspend fun `enableRecovery`(): kotlin.String
    
    /**
     * Fetch the avatar at the given MXC URI into a file, returning its
     * path.
     */
    suspend fun `getAvatar`(`mxcUri`: kotlin.String, `size`: kotlin.UInt): kotlin.String?
    
    /**
     * Fetch the avatar of the given room into a file, returning its path.
     */
    suspend fun `getRoomAvatar`(`roomId`: kotlin.String, `size`: kotlin.UInt): kotlin.String?
    
    /**
     * Fetch the image of the given timeline item into a file, returning
     * its path.
     *
     * The item is looked up in the room's timeline so that encrypted
     * sources come with their keys; only image messages are handled for
     * now.
     */
    suspend fun `getTimelineMedia`(`roomId`: kotlin.String, `uniqueId`: kotlin.String): kotlin.String?
    
    /**
     * Whether a session is logged in and running.
     *
     * Restoration is asynchronous: after [`Self::restore_sessions()`] this
     * turns true once the stored session has finished coming up.
     */
    fun `hasReadySession`(): kotlin.Boolean
    
    /**
     * Whether there are sessions on this device, in any state.
     */
    fun `hasSessions`(): kotlin.Boolean
    
    /**
     * Join the room with the given ID or alias. Returns the room ID.
     */
    suspend fun `joinRoom`(`roomIdOrAlias`: kotlin.String): kotlin.String
    
    /**
     * Log in with a password on the given homeserver.
     */
    suspend fun `loginWithPassword`(`homeserver`: kotlin.String, `username`: kotlin.String, `password`: kotlin.String)
    
    /**
     * Mark the given room as read, sending a read receipt at the end of
     * its timeline.
     */
    suspend fun `markRoomRead`(`roomId`: kotlin.String)
    
    /**
     * Paginate the given room's timeline backwards.
     */
    suspend fun `paginateBackwards`(`roomId`: kotlin.String)
    
    /**
     * Recover the account's secrets with the given recovery key.
     */
    suspend fun `recover`(`recoveryKey`: kotlin.String)
    
    /**
     * Where account recovery stands for the first ready session.
     */
    suspend fun `recoveryState`(): FfiRecoveryState
    
    /**
     * Redact the given event in the given room.
     */
    suspend fun `redactEvent`(`roomId`: kotlin.String, `eventId`: kotlin.String)
    
    /**
     * Ask the account's verified sessions to verify this one. The flow
     * then arrives through the listener like an incoming one: emojis,
     * then done.
     */
    suspend fun `requestVerification`(): kotlin.String
    
    /**
     * Restore the sessions stored on this device.
     */
    suspend fun `restoreSessions`()
    
    /**
     * A snapshot of the given room's members, loading the list on first
     * use — the composer's mention completion reads this.
     */
    suspend fun `roomMembers`(`roomId`: kotlin.String): List<FfiMember>
    
    /**
     * The rooms of the first ready session, as of now.
     */
    fun `rooms`(): List<FfiRoom>
    
    /**
     * Feed a scanned QR code into the verification with the given flow
     * ID. The outcome arrives through the listener: done, or cancelled.
     */
    suspend fun `scanQr`(`flowId`: kotlin.String, `data`: kotlin.ByteArray)
    
    /**
     * Send the file at the given path as an attachment to the given room.
     */
    suspend fun `sendAttachment`(`roomId`: kotlin.String, `filePath`: kotlin.String, `mimeType`: kotlin.String)
    
    /**
     * Send a message to the given room — Markdown, as the composer
     * writes it — mentioning the given users.
     */
    suspend fun `sendMessage`(`roomId`: kotlin.String, `body`: kotlin.String, `mentions`: List<kotlin.String>)
    
    /**
     * Send a plain-text reply to the given event in the given room.
     */
    suspend fun `sendReply`(`roomId`: kotlin.String, `inReplyTo`: kotlin.String, `body`: kotlin.String)
    
    /**
     * Send a plain-text message into the thread rooted at the given
     * event.
     */
    suspend fun `sendThreadMessage`(`roomId`: kotlin.String, `rootEventId`: kotlin.String, `body`: kotlin.String)
    
    /**
     * Send a typing notification for the given room.
     *
     * Owned `String` because the FFI hands one over.
     */
    fun `sendTyping`(`roomId`: kotlin.String, `isTyping`: kotlin.Boolean)
    
    /**
     * The display name of the first ready session's user, if it is known.
     */
    fun `sessionDisplayName`(): kotlin.String?
    
    /**
     * The current session's settings.
     */
    fun `sessionSettings`(): FfiSessionSettings?
    
    /**
     * The Matrix user ID of the first ready session, if any.
     */
    fun `sessionUserId`(): kotlin.String?
    
    /**
     * Give the member list of the given room to the given listener, now
     * and on every change.
     *
     * Replaces any previous member-list listener; v1 watches one room at
     * a time, which is what one screen shows.
     */
    fun `setMemberListListener`(`roomId`: kotlin.String, `listener`: MemberListListener)
    
    /**
     * Set whether notifications are enabled for this session.
     */
    fun `setNotificationsEnabled`(`enabled`: kotlin.Boolean)
    
    /**
     * Give the room's pinned events to the given listener, now and on
     * every change.
     *
     * Replaces any previous pinned listener.
     */
    fun `setPinnedListener`(`roomId`: kotlin.String, `listener`: TimelineListener)
    
    /**
     * Set whether read receipts are public for this session.
     */
    fun `setPublicReadReceiptsEnabled`(`enabled`: kotlin.Boolean)
    
    /**
     * Set the given room's name and topic.
     */
    suspend fun `setRoomDetails`(`roomId`: kotlin.String, `name`: kotlin.String, `topic`: kotlin.String)
    
    /**
     * Give the room list of the first ready session to the given listener,
     * now and on every change.
     *
     * Replaces any previous listener.
     */
    fun `setRoomListListener`(`listener`: RoomListListener)
    
    /**
     * Give the thread rooted at the given event to the given listener,
     * now and on every change. Replaces any previous thread listener.
     */
    fun `setThreadListener`(`roomId`: kotlin.String, `rootEventId`: kotlin.String, `listener`: TimelineListener)
    
    /**
     * Give the timeline of the given room to the given listener, now and
     * on every change.
     *
     * Replaces any previous timeline listener; v1 watches one room at a
     * time, which is what one screen shows.
     */
    fun `setTimelineListener`(`roomId`: kotlin.String, `listener`: TimelineListener)
    
    /**
     * Set whether typing notifications are sent for this session.
     */
    fun `setTypingEnabled`(`enabled`: kotlin.Boolean)
    
    /**
     * Give the typing users of the given room to the given listener, now
     * and on every change. Replaces any previous typing listener.
     */
    fun `setTypingListener`(`roomId`: kotlin.String, `listener`: TypingListener)
    
    /**
     * Follow device verifications with the given listener, accepting
     * the flows the listener's side approves.
     *
     * Replaces any previous listener; registering starts watching for
     * incoming requests.
     */
    fun `setVerificationListener`(`listener`: VerificationListener)
    
    /**
     * The rooms inside the given space, from the server's hierarchy.
     */
    suspend fun `spaceChildren`(`spaceId`: kotlin.String): List<FfiSpaceChild>
    
    /**
     * Toggle the given reaction on the given event in the given room.
     */
    suspend fun `toggleReaction`(`roomId`: kotlin.String, `eventId`: kotlin.String, `key`: kotlin.String)
    
    companion object
}

/**
 * The core, as one object the foreign side holds.
 */
open class CoreApp: Disposable, AutoCloseable, CoreAppInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }
    /**
     * Create the core. [`init_core()`] must have been called.
     */
    constructor() :
        this(UniffiWithHandle, 
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_commune_core_fn_constructor_coreapp_new(
    
        _status)
}
    )

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_commune_core_fn_free_coreapp(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_commune_core_fn_clone_coreapp(handle, status)
        }
    }

    
    /**
     * Accept the verification with the given flow ID; the emojis arrive
     * through the listener when both sides are ready.
     */
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `acceptVerification`(`flowId`: kotlin.String) {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_commune_core_fn_method_coreapp_accept_verification(
                uniffiHandle,
                FfiConverterString.lower(`flowId`),
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_commune_core_rust_future_poll_void(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_commune_core_rust_future_complete_void(future, continuation) },
        { future -> UniffiLib.ffi_commune_core_rust_future_free_void(future) },
        // lift function
        { Unit },
        
        // Error FFI converter
        UniffiNullRustCallStatusErrorHandler,
    )
    }

    
    /**
     * Cancel the verification — the emojis did not match, or the user
     * declined.
     */
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `cancelVerification`(`flowId`: kotlin.String) {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_commune_core_fn_method_coreapp_cancel_verification(
                uniffiHandle,
                FfiConverterString.lower(`flowId`),
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_commune_core_rust_future_poll_void(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_commune_core_rust_future_complete_void(future, continuation) },
        { future -> UniffiLib.ffi_commune_core_rust_future_free_void(future) },
        // lift function
        { Unit },
        
        // Error FFI converter
        UniffiNullRustCallStatusErrorHandler,
    )
    }

    
    /**
     * Move the given room to the given category: accepting an invite is a
     * move to Normal, declining it (or leaving) a move to Left.
     */
    @Throws(CoreException::class)
