/**
 * An error handed across the FFI.
 */
sealed class CoreException: kotlin.Exception() {
    
    /**
     * The operation failed; the message is displayable.
     */
    class Failed(
        
        /**
         * The displayable message.
         */
        val `msg`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * What kind of event a timeline item is.
 */
sealed class FfiEventKind {
    
    /**
     * A text-like message (`m.text`, `m.notice`, `m.emote`).
     */
    object Text : FfiEventKind()
    
    
    /**
     * A media message; the body is the caption or filename.
     */
    data class Media(
        /**
         * Whether the media is an image the timeline can show inline
         * (fetch it with `get_timeline_media`).
         */
        val `kind`: io.github.steeb_k.commune.core.FfiMediaKind) : FfiEventKind()
        
    {
        

        companion object
    }
    
    /**
     * A sticker.
     */
    object Sticker : FfiEventKind()
    
    
    /**
     * A message that could not be decrypted.
     */
    object UnableToDecrypt : FfiEventKind()
    
    
    /**
     * A redacted message.
     */
    object Redacted : FfiEventKind()
    
    
    /**
     * A membership change; the UI words the sentence.
     */
    data class Membership(
        /**
         * The user whose membership changed.
         */
        val `user`: kotlin.String, 
        /**
         * What happened.
         */
        val `change`: io.github.steeb_k.commune.core.FfiMembershipChange) : FfiEventKind()
        
    {
        

        companion object
    }
    
    /**
     * A member changed their profile.
     */
    data class ProfileChange(
        /**
         * The user whose profile changed.
         */
        val `user`: kotlin.String) : FfiEventKind()
        
    {
        

        companion object
    }
    
    /**
     * Another state event.
     */
    data class OtherState(
        /**
         * What changed.
         */
        val `change`: io.github.steeb_k.commune.core.FfiStateChange) : FfiEventKind()
        
    {
        

        companion object
    }
    
    /**
     * Something not handled yet.
     */
    object Unsupported : FfiEventKind()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiEventKind : FfiConverterRustBuffer<FfiEventKind>{
    override fun read(buf: ByteBuffer): FfiEventKind {
        return when(buf.getInt()) {
            1 -> FfiEventKind.Text
            2 -> FfiEventKind.Media(
                FfiConverterTypeFfiMediaKind.read(buf),
                )
            3 -> FfiEventKind.Sticker
            4 -> FfiEventKind.UnableToDecrypt
            5 -> FfiEventKind.Redacted
            6 -> FfiEventKind.Membership(
                FfiConverterString.read(buf),
                FfiConverterTypeFfiMembershipChange.read(buf),
                )
            7 -> FfiEventKind.ProfileChange(
                FfiConverterString.read(buf),
                )
            8 -> FfiEventKind.OtherState(
                FfiConverterTypeFfiStateChange.read(buf),
                )
            9 -> FfiEventKind.Unsupported
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiEventKind) = when(value) {
        is FfiEventKind.Text -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiEventKind.Media -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiMediaKind.allocationSize(value.`kind`)
            )
        }
        is FfiEventKind.Sticker -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiEventKind.UnableToDecrypt -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiEventKind.Redacted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiEventKind.Membership -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`user`)
                + FfiConverterTypeFfiMembershipChange.allocationSize(value.`change`)
            )
        }
        is FfiEventKind.ProfileChange -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`user`)
            )
        }
        is FfiEventKind.OtherState -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiStateChange.allocationSize(value.`change`)
            )
        }
        is FfiEventKind.Unsupported -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: FfiEventKind, buf: ByteBuffer) {
        when(value) {
            is FfiEventKind.Text -> {
                buf.putInt(1)
                Unit
            }
            is FfiEventKind.Media -> {
                buf.putInt(2)
                FfiConverterTypeFfiMediaKind.write(value.`kind`, buf)
                Unit
            }
            is FfiEventKind.Sticker -> {
                buf.putInt(3)
                Unit
            }
            is FfiEventKind.UnableToDecrypt -> {
                buf.putInt(4)
                Unit
            }
            is FfiEventKind.Redacted -> {
                buf.putInt(5)
                Unit
            }
            is FfiEventKind.Membership -> {
                buf.putInt(6)
                FfiConverterString.write(value.`user`, buf)
                FfiConverterTypeFfiMembershipChange.write(value.`change`, buf)
                Unit
            }
            is FfiEventKind.ProfileChange -> {
                buf.putInt(7)
                FfiConverterString.write(value.`user`, buf)
                Unit
            }
            is FfiEventKind.OtherState -> {
                buf.putInt(8)
                FfiConverterTypeFfiStateChange.write(value.`change`, buf)
                Unit
            }
            is FfiEventKind.Unsupported -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





